// -- Global State --
let particles = [];
let fRate = 3; 
let cState = 0; 
let showLabels = true;
const cycleStates = ["Idle", "Oxidation at Anode", "Current & Ion Flow", "Reduction at Cathode"];
let fuelCounter = 0;
let oxygenCounter = 0;

let waitAnodeH = [];
let waitAnodeE = [];
let waitCathodeO2 = [];
let waitCathodeH = [];
let waitCathodeE = [];

// -- UI Bindings --
window.update_fuelCellCycle = function(val) {
  let idx = typeof val === 'string' ? cycleStates.indexOf(val) : val;
  if (idx < 0) idx = 0;
  cState = idx;
  const btn = document.getElementById('fuelCellCycleBtn');
  btn.textContent = "State: " + cycleStates[cState];
  btn.classList.add('active');
  setTimeout(() => btn.classList.remove('active'), 200);
};

window.trigger_fuelCellCycle = function() {
  update_fuelCellCycle((cState + 1) % cycleStates.length);
};

window.update_h2FeedRate = function(v) { fRate = v; };

window.toggle_viewMode = function(isChecked) {
  showLabels = isChecked;
  if (showLabels) labelGroup.show();
  else labelGroup.hide();
};

// -- Demo Player --
const demoSteps = [
  { title: "The Fuel Cell Structure", narration: "A fuel cell consists of two electrodes (anode and cathode) separated by a proton exchange membrane. Reactants flow in, and products flow out.", state: { fuelCellCycle: "Idle", h2FeedRate: 3, viewMode: "Fully labeled" } },
  { title: "Oxidation at the Anode", narration: "Hydrogen gas enters the left side and is oxidized at the anode, splitting into positively charged protons (H+) and negatively charged electrons (e-).", state: { fuelCellCycle: "Oxidation at Anode", h2FeedRate: 3, viewMode: "Fully labeled" } },
  { title: "Generating Current", narration: "The central membrane only allows protons to pass. To reach the other side, electrons are forced to travel through the external circuit, generating electric power.", state: { fuelCellCycle: "Current & Ion Flow", h2FeedRate: 3, viewMode: "Fully labeled" } },
  { title: "Reduction and Water Formation", narration: "At the cathode, the arriving protons and electrons combine with incoming oxygen gas to produce water, the only byproduct of this process.", state: { fuelCellCycle: "Reduction at Cathode", h2FeedRate: 3, viewMode: "Fully labeled" } },
  { title: "Adjusting Power Output", narration: "Increasing the supply of hydrogen fuel directly increases both the electrical current generated and the amount of water produced.", state: { fuelCellCycle: "Reduction at Cathode", h2FeedRate: 5, viewMode: "Fully labeled" } },
  { title: "Continuous Flow", narration: "In operation, all these steps happen simultaneously, creating a continuous conversion of chemical energy into electrical energy.", state: { fuelCellCycle: "Reduction at Cathode", h2FeedRate: 5, viewMode: "Clean flow schematic" } }
];
