// -- Particle System & Animation Engine --
function spawnParticle(type, x, y) {
  let g = particleGroup.group();
  if (type === 'H2') {
    g.circle(14).fill('#FFF').stroke({width: 1, color: '#999'}).center(-6, 0);
    g.circle(14).fill('#FFF').stroke({width: 1, color: '#999'}).center(6, 0);
  } else if (type === 'O2') {
    g.circle(16).fill('#E03030').stroke({width: 1, color: '#999'}).center(-7, 0);
    g.circle(16).fill('#E03030').stroke({width: 1, color: '#999'}).center(7, 0);
  } else if (type === 'H2O') {
    g.circle(16).fill('#E03030').stroke({width: 1, color: '#999'}).center(0, 0);
    g.circle(12).fill('#FFF').stroke({width: 1, color: '#999'}).center(-8, 7);
    g.circle(12).fill('#FFF').stroke({width: 1, color: '#999'}).center(8, 7);
  } else if (type === 'H+') {
    g.circle(14).fill('#FFF').stroke({width: 1, color: '#999'}).center(0, 0);
    g.line(-3, 0, 3, 0).stroke({width: 1.5, color: '#000', linecap: 'round'});
    g.line(0, -3, 0, 3).stroke({width: 1.5, color: '#000', linecap: 'round'});
  } else if (type === 'e-') {
    g.circle(12).fill('#FFD700').stroke({width: 1, color: '#999'}).center(0, 0);
    g.line(-3, 0, 3, 0).stroke({width: 1.5, color: '#000', linecap: 'round'});
  }
  g.center(x, y);
  let p = { type, el: g, x, y, state: 'moving', path: [], pathIdx: 0 };
  particles.push(p);
  return p;
}

function removeParticle(p) {
  p.el.remove();
  let idx = particles.indexOf(p);
  if (idx > -1) particles.splice(idx, 1);
}

function updateFrame() {
  // Electric glow
  if (cState >= 2) glow.opacity(0.6 + Math.sin(Date.now() / 150) * 0.3);
  else glow.opacity(0);

  // Spawning H2
  fuelCounter += (fRate * 0.02);
  while (fuelCounter >= 1) {
    fuelCounter -= 1;
    let yOff = Math.random() * 20 - 10;
    let p = spawnParticle('H2', 100, 215 + yOff);
    p.path = [{x: 280 + (Math.random()*10 - 5), y: 215 + yOff}];
    p.onTarget = () => {
      if (cState == 0 || (cState == 1 && waitAnodeH.length >= 8) || Math.random() < 0.15) {
        p.path = [{x: p.x, y: 425 + yOff}, {x: 100, y: 425 + yOff}];
        p.onTarget = () => removeParticle(p);
      } else {
        p.path = [{x: 320, y: 220 + Math.random()*200}];
        p.onTarget = () => {
          let h1 = spawnParticle('H+', p.x, p.y - 6);
          let h2 = spawnParticle('H+', p.x, p.y + 6);
          let e1 = spawnParticle('e-', p.x - 8, p.y - 6);
          let e2 = spawnParticle('e-', p.x - 8, p.y + 6);
          waitAnodeH.push(h1, h2);
          waitAnodeE.push(e1, e2);
          removeParticle(p);
        };
      }
    };
  }

  // Releasing H+ and e- from Anode
  if (cState >= 2) {
    waitAnodeH.forEach(h => {
      h.path = [{x: 480, y: h.y + (Math.random()*20 - 10)}];
      h.pathIdx = 0;
      h.state = 'moving';
      h.onTarget = () => { waitCathodeH.push(h); h.state = 'idle'; };
    });
    waitAnodeH = [];

    waitAnodeE.forEach(e => {
      let destY = 220 + Math.random()*200;
      let xOff = Math.random()*10 - 5;
      e.path = [
        {x: 340 + xOff, y: e.y},
        {x: 340 + xOff, y: 60 + xOff/2},
        {x: 460 - xOff, y: 60 + xOff/2},
        {x: 460 - xOff, y: destY},
        {x: 480, y: destY}
      ];
      e.pathIdx = 0;
      e.state = 'moving';
      e.onTarget = () => { waitCathodeE.push(e); e.state = 'idle'; };
    });
    waitAnodeE = [];
  }

  // Spawning O2 and Water Formation
  if (cState >= 3) {
    oxygenCounter += (fRate * 0.02) / 2;
    while (oxygenCounter >= 1) {
      oxygenCounter -= 1;
      let yOff = Math.random() * 20 - 10;
      let p = spawnParticle('O2', 700, 215 + yOff);
      p.path = [{x: 520 + (Math.random()*10 - 5), y: 215 + yOff}];
      p.onTarget = () => {
        p.path = [{x: 480, y: 220 + Math.random()*200}];
        p.onTarget = () => { waitCathodeO2.push(p); p.state = 'idle'; };
      };
    }

    while (waitCathodeO2.length >= 1 && waitCathodeH.length >= 4 && waitCathodeE.length >= 4) {
      let o2 = waitCathodeO2.shift();
      let hList = waitCathodeH.splice(0, 4);
      let eList = waitCathodeE.splice(0, 4);
      let wY = o2.y;

      removeParticle(o2);
      hList.forEach(removeParticle);
      eList.forEach(removeParticle);

      for(let i=0; i<2; i++) {
        let w = spawnParticle('H2O', 480, wY + (i*14 - 7));
        w.path = [
          {x: 520 + (Math.random()*10 - 5), y: w.y},
          {x: 520, y: 425 + (Math.random()*20 - 10)},
          {x: 700, y: 425 + (Math.random()*20 - 10)}
        ];
        w.onTarget = () => removeParticle(w);
      }
    }
  }

  // Move particles
  let speedBase = 1.5 + (fRate * 0.4);
  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    if (p.state === 'idle') continue;

    let target = p.path[p.pathIdx];
    let dx = target.x - p.x;
    let dy = target.y - p.y;
    let dist = Math.sqrt(dx*dx + dy*dy);

    let speed = speedBase;
    if (p.type === 'e-') speed *= 3.0; // Fast external circuit
    if (p.type === 'H+') speed *= 0.6; // Slow membrane crossing

    if (dist < speed) {
      p.x = target.x;
      p.y = target.y;
      p.pathIdx++;
      if (p.pathIdx >= p.path.length) {
        if (p.onTarget) p.onTarget();
        else removeParticle(p);
      }
    } else {
      p.x += (dx / dist) * speed;
      p.y += (dy / dist) * speed;
    }
    p.el.center(p.x, p.y);
  }
}

let isRunning = true;
function loop() {
  if (isRunning) {
    updateFrame();
    requestAnimationFrame(loop);
  }
}
loop();

